  raw=bytes(int(v,16) for v in f['idaBytes'].split());at=int(f['addr'],16)
  for row in f['disassembly']['asm']['lines']:
   pc=int(row['addr'],16);i=next(cs.disasm(raw[pc-at:pc-at+15],pc,count=1));allins[pc]=i
